const $=s=>document.querySelector(s), msg={set textContent(value){const main=$('#message');if(main)main.textContent=value;const detail=$('#detail-message');if(detail)detail.textContent=value},get textContent(){return $('#message')?.textContent||''}};let config,token,user,profile,leads=[],agents=[],selected;
let detailTab='overview';
let responseTimer=null,contactEvents=[],contactReady=false;
function stopResponseTimer(){if(responseTimer!==null){clearInterval(responseTimer);responseTimer=null}}

let refreshTimer=null,rememberSession=false,refreshSecret=null;
function clearSession(){rememberSession=false;refreshSecret=null;if(refreshTimer)clearTimeout(refreshTimer);if(typeof localStorage!=='undefined')localStorage.removeItem('trustlane-session');}
function acceptSession(d,remember){token=d.access_token;user=d.user||user;refreshSecret=d.refresh_token;rememberSession=remember;if(typeof localStorage!=='undefined'){if(remember)localStorage.setItem('trustlane-session',JSON.stringify({refresh_token:refreshSecret}));else localStorage.removeItem('trustlane-session');}if(refreshTimer)clearTimeout(refreshTimer);refreshTimer=setTimeout(refreshSession,Math.max(30000,((d.expires_in||3600)-60)*1000));}
async function refreshSession(){if(!refreshSecret)return;const secret=refreshSecret;try{const r=await fetch(config.supabaseUrl+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:config.supabaseAnonKey,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:secret})});if(!r.ok){if(r.status===400||r.status===401){clearSession();token=null;msg.textContent='Your session expired. Please sign in again.';$('#dashboard').hidden=true;$('#login').hidden=false;return}throw Error('Refresh unavailable');}const d=await r.json();if(refreshSecret===secret)acceptSession(d,rememberSession)}catch{if(refreshSecret===secret)refreshTimer=setTimeout(refreshSession,30000)}}
function selectDetailTab(tab){detailTab=tab;document.querySelectorAll('#detail [data-detail-panel]').forEach(p=>{p.hidden=p.dataset.detailPanel!==tab});document.querySelectorAll('#detail [data-detail-tab]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.detailTab===tab))});}
function closeDetail(){stopResponseTimer();selected=null;$('#detail').classList.remove('is-open');$('#detail').innerHTML='<div class="empty-detail"><h2>Your next move starts here.</h2><p>Select a lead to see its details.</p></div>';}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,opts={}) {const r=await fetch(config.supabaseUrl+path,{...opts,headers:{apikey:config.supabaseAnonKey,Authorization:`Bearer ${token||config.supabaseAnonKey}`,'Content-Type':'application/json',...(opts.headers||{})}});let d;try{d=await r.json()}catch{d=null}if(!r.ok)throw Error(d?.msg||d?.message||'Request failed. Please try again.');return d;}
async function fetchAll(path){const all=[];const pageSize=1000;for(let offset=0;;offset+=pageSize){const page=await api(path+(path.includes('?')?'&':'?')+'limit='+pageSize+'&offset='+offset);if(!Array.isArray(page))throw Error('Could not load the complete list.');all.push(...page);if(page.length<pageSize)return all;}}
async function load(){profile=(await api(`/rest/v1/trustlane_profiles?user_id=eq.${user.id}&select=*`))[0];if(!profile||!profile.active)throw Error('Your account is not enabled for this portal.');leads=await fetchAll('/rest/v1/trustlane_quote_requests?select=*&order=created_at.desc,id.desc');agents=profile.role==='admin'?await api('/rest/v1/trustlane_profiles?role=eq.agent&select=user_id,display_name,active'):[];$('#login').hidden=true;$('#dashboard').hidden=false;$('#who').textContent=profile.display_name+' · '+profile.role;$('#agent-management').hidden=profile.role!=='admin';$('#stat-total').textContent=leads.length;$('#stat-new').textContent=leads.filter(l=>l.status==='New').length;$('#stat-progress').textContent=leads.filter(l=>['Assigned','Contacted','Quoted'].includes(l.status)).length;$('#stat-booked').textContent=leads.filter(l=>l.status==='Booked').length;$('#agent-list').innerHTML=agents.map(a=>`<div class="agent-row"><span><strong>${esc(a.display_name)}</strong><small>${a.active?'Active':'Inactive'}</small></span><button type="button" data-agent="${esc(a.user_id)}" data-active="${a.active}">${a.active?'Deactivate':'Reactivate'}</button></div>`).join('')||'<p class="team-empty">No agents added yet.</p>';render();await loadOverview();}
async function loadOverview(){const tasks=await fetchAll('/rest/v1/trustlane_tasks?completed=eq.false&select=id,lead_id,title,due_on&order=due_on.asc.nullslast,created_at.asc,id.asc');const visible=tasks.filter(t=>leads.some(l=>l.id===t.lead_id));$('#overview-count').textContent=visible.length+' open';$('#task-overview').innerHTML=visible.map(t=>{const lead=leads.find(l=>l.id===t.lead_id);return `<button type="button" class="overview-task" data-lead="${esc(t.lead_id)}"><strong>${esc(t.title)}</strong><span>${esc(lead.name)} · ${t.due_on?'Due '+esc(t.due_on):'No due date'}</span></button>`}).join('')||'<p class="team-empty">No open follow-ups.</p>';}
function renderWork(l){const fields=[['name','Customer name','text',true],['email','Email','email',true],['phone','Phone','tel',true],['pickup','Pickup','text',true],['delivery','Delivery','text',true],['pickup_address','Full pickup address','text',false],['delivery_address','Full delivery address','text',false],['vehicle_year','Vehicle year','number',true],['vehicle_make','Vehicle make','text',true],['vehicle_model','Vehicle model','text',true],['preferred_date','Preferred shipping date','date',true],['desired_delivery_on','Desired delivery date','date',false],['carrier_pay','Carrier pay','number',false],['quote_expires_on','Quote expiration','date',false],['reference_number','Reference number','text',false]];const options=(current,values)=>values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v||'Not set')}</option>`).join('');$('#working-details').innerHTML=`<details class="working-details" open><summary><strong>Shipment and quote details</strong></summary><p>Save working details here. Amounts are entered by your team; saving them does not send a quote or book a shipment.</p><form id="working-form"><div class="working-grid">${fields.map(([key,label,type,required])=>`<label>${esc(label)}<input name="${key}" type="${type}" value="${esc(l[key]??'')}" ${required?'required':''} ${key==='vehicle_year'?'min="1886" max="2100"':''} ${['quote_amount','carrier_pay'].includes(key)?'min="0" max="9999999999" step="0.01"':''}></label>`).join('')}<label>Working status<select name="working_status">${options(l.working_status||'',['','New','Hot','Warm','Cold','On Hold','Follow Up','Email Sent','Voicemail','No Answer','Searching For Carriers','Carrier Assigned','Dispatched','Picked Up','In Transit','Delivered'])}</select></label><label>Transport type<select name="transport_type">${options(l.transport_type||'',['','Open','Enclosed'])}</select></label></div><label>Customer details<textarea name="details" maxlength="2000">${esc(l.details||'')}</textarea></label><label>Special terms<textarea name="special_terms" maxlength="2000">${esc(l.special_terms||'')}</textarea></label><button class="button primary">Save shipment details</button></form></details>`;$('#working-form').onsubmit=saveWorking;}
async function saveWorking(e){e.preventDefault();const f=new FormData(e.target), data=Object.fromEntries(f);data.carrier_pay=data.carrier_pay===''?null:Number(data.carrier_pay);for(const k of ['quote_expires_on','desired_delivery_on'])data[k]=data[k]||null;data.vehicle_year=Number(data.vehicle_year);if(selected.quote_amount!=null&&data.carrier_pay!==null&&data.carrier_pay>Number(selected.quote_amount)){msg.textContent='Carrier pay cannot exceed the customer quote amount.';return}const id=selected.id;try{const updated=await api('/rest/v1/trustlane_quote_requests?id=eq.'+encodeURIComponent(id),{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify(data)});if(!Array.isArray(updated)||updated.length!==1)throw Error('Lead could not be updated. Refresh and try again.');await load();await detail(id);msg.textContent='Shipment details saved.'}catch(err){msg.textContent=err.message}}
async function loadActivity(id){const entries=await api(`/rest/v1/trustlane_lead_activity?lead_id=eq.${encodeURIComponent(id)}&select=actor_id,occurred_at,changes&order=occurred_at.desc&limit=100`);const labels={status:'Pipeline status',closed_outcome:'Closed outcome',assigned_to:'Assignment',working_status:'Working status',transport_type:'Transport type',quote_amount:'Customer quote',carrier_pay:'Carrier pay',quote_expires_on:'Quote expiration',desired_delivery_on:'Desired delivery'};$('#activity-list').innerHTML=entries.map(entry=>{const lines=Object.entries(entry.changes||{}).filter(([key])=>labels[key]).map(([key,change])=>key==='assigned_to'?'Assignment changed':`${labels[key]}: ${change.from??'—'} → ${change.to??'—'}`);return `<div class="note"><small>${esc(new Date(entry.occurred_at).toLocaleString())} · ${esc(entry.actor_id===user.id?"You":agents.find(a=>a.user_id===entry.actor_id)?.display_name||"Team member")}</small><br>${lines.map(esc).join('<br>')}</div>`}).join('')||'<p class="team-empty">No recorded changes yet.</p>';}
function responseText(lead,events,now=Date.now()){const arrived=Date.parse(lead.created_at);if(!Number.isFinite(arrived))return {text:'Arrival time unavailable',overdue:false};const first=events.filter(e=>['Call','Text','Email','Voicemail'].includes(e.kind)).map(e=>Date.parse(e.created_at)).filter(t=>Number.isFinite(t)&&t>=arrived).sort((a,b)=>a-b)[0];const elapsed=Math.max(0,Math.floor(((first??now)-arrived)/1000));const format=n=>n>=86400?Math.floor(n/86400)+'d '+Math.floor(n%86400/3600)+'h':n>=3600?Math.floor(n/3600)+'h '+Math.floor(n%3600/60)+'m':Math.floor(n/60)+':'+String(n%60).padStart(2,'0');return first!==undefined?{text:'First attempt logged in '+format(elapsed),overdue:elapsed>30}:{text:elapsed<30?'Response target: '+(30-elapsed)+'s remaining':'Response target overdue by '+format(elapsed-30),overdue:elapsed>=30};}
function updateResponse(){if(!selected||!contactReady)return;const el=$('#response-timer');if(!el)return;const state=responseText(selected,contactEvents);el.textContent=state.text;el.classList.toggle('overdue',state.overdue);}
function locationZip(location){const text=String(location||'').trim();const matches=text.match(/\b\d{5}(?:-\d{4})?\b/g)||[];return matches.length===1&&text.endsWith(matches[0])?matches[0]:'';}
function completeVehicle(l){return l.vehicle_year&&String(l.vehicle_make||'').trim()&&String(l.vehicle_model||'').trim()?[l.vehicle_year,l.vehicle_make,l.vehicle_model].join(' '):'';}
function assignedName(l){return profile.role==='admin'?(agents.find(a=>a.user_id===l.assigned_to)?.display_name||(l.assigned_to?'Assigned agent':'Unassigned')):(l.assigned_to===user.id?profile.display_name:(l.assigned_to?'Assigned agent':'Unassigned'));}
async function copyValue(label,value){if(!value){msg.textContent=label+' is missing.';return}try{if(!navigator.clipboard?.writeText)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(value);msg.textContent=label+' copied.'}catch{msg.textContent='Copy failed. Select the displayed details and copy them manually.'}}
const zipCache=new Map();
function zipMarkup(kind,location){const zip=locationZip(location);return zip?`<button type="button" class="zip-copy" data-copy-field="${kind}" aria-label="Copy ${kind} ZIP ${esc(zip)}" title="Copy ZIP">${esc(zip)} <span aria-hidden="true">?</span></button><small id="${kind}-lookup" role="status"></small>`:'<small>ZIP not recorded or invalid</small>';}
function bindCopyButtons(l){document.querySelectorAll('#detail [data-copy-field]').forEach(button=>{button.onclick=async()=>{const zip=locationZip(l[button.dataset.copyField]);try{if(!navigator.clipboard?.writeText)throw Error();await navigator.clipboard.writeText(zip);const before=button.innerHTML;button.textContent=zip+' ? Copied';msg.textContent='ZIP copied.';setTimeout(()=>{if(button.isConnected)button.innerHTML=before},2000)}catch{msg.textContent='Copy failed. Select the ZIP and copy it manually.'}}});}
async function lookupLocation(l,kind,retry=false){const raw=String(l[kind]||'').trim(),zip=locationZip(raw),el=$('#'+kind+'-lookup');if(!el||!/^\d{5}(?:-\d{4})?$/.test(raw)||!zip)return;el.textContent='Looking up city and state?';try{const key=zip.slice(0,5);if(retry)zipCache.delete(key);if(!zipCache.has(key)){const promise=fetch('/api/lookup?kind=zip&zip='+key).then(async r=>{if(!r.ok)throw Error(r.status===404?'No city found for this ZIP.':'Location lookup unavailable.');return r.json()}).catch(e=>{zipCache.delete(key);throw e});zipCache.set(key,promise)}const data=await zipCache.get(key);if(!selected||selected.id!==l.id||!el.isConnected)return;const places=data.places||[];el.textContent=places.length===1?places[0]+' (lookup; verify in Shipment)':places.length>1?'Multiple matches: '+places.join('; ')+'. Verify in Shipment.':'No city found; verify in Shipment.'}catch(err){if(!el.isConnected)return;el.textContent=err.message+' ';const button=document.createElement('button');button.type='button';button.textContent='Retry';button.onclick=()=>lookupLocation(l,kind,true);el.append(button)}}
async function saveQuickPrice(){const raw=$('#quick-price').value.trim(),amount=Number(raw);if(!raw||!Number.isFinite(amount)||amount<0||amount>9999999999||!/^\d+(?:\.\d{1,2})?$/.test(raw))throw Error('Enter a valid customer quote amount.');if(selected.carrier_pay!=null&&Number(selected.carrier_pay)>amount)throw Error('Customer quote cannot be less than carrier pay.');const id=selected.id;const rows=await api('/rest/v1/trustlane_quote_requests?id=eq.'+encodeURIComponent(id),{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({quote_amount:amount})});if(!Array.isArray(rows)||rows.length!==1)throw Error('Price could not be saved. Refresh and try again.');if(!selected||selected.id!==id)throw Error('Lead changed. Reopen it and try again.');selected=rows[0];const index=leads.findIndex(l=>l.id===id);if(index>=0)leads[index]=rows[0];return rows[0];}
async function saveQuickQuote(e){e.preventDefault();const b=$('#save-price');b.disabled=true;try{$('#quick-quote-message').value='';$('#copy-quote-text').disabled=true;$('#open-quote-text').disabled=true;$('#prepare-quote').disabled=true;$('#quick-price').disabled=true;await saveQuickPrice();msg.textContent='Customer quote saved. It has not been sent.'}catch(err){msg.textContent=err.message}finally{b.disabled=false;$('#prepare-quote').disabled=false;$('#quick-price').disabled=false}}
async function prepareQuoteText(){const button=$('#prepare-quote');button.disabled=true;$('#save-price').disabled=true;$('#quick-price').disabled=true;$('#quick-quote-message').value='';$('#copy-quote-text').disabled=true;$('#open-quote-text').disabled=true;try{const lead=await saveQuickPrice(),id=lead.id;const quote=await api('/rest/v1/rpc/trustlane_create_quote_draft',{method:'POST',body:JSON.stringify({p_lead_id:id})});if(!selected||selected.id!==id)throw Error('Lead changed. Reopen it and try again.');const bytes=crypto.getRandomValues(new Uint8Array(32));const token=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(token));const hash=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');await api('/rest/v1/rpc/trustlane_issue_booking_link',{method:'POST',body:JSON.stringify({p_lead_id:id,p_quote_id:quote,p_token_hash:hash})});if(!selected||selected.id!==id)throw Error('Lead changed. Reopen it and try again.');const link=location.origin+'/booking.html#'+token;$('#quick-quote-message').value='Hello '+lead.name+',\n\nYour vehicle transport quote is $'+Number(lead.quote_amount).toFixed(2)+'. Review the shipment and agreement here: '+link+'\n\nTrustlane Transportation';$('#copy-quote-text').disabled=false;$('#open-quote-text').disabled=String(lead.phone||'').replace(/\D/g,'').length<7;msg.textContent='Quote and booking link prepared. No message has been sent.';await loadQuotes(id);await loadSigning(id);}catch(err){msg.textContent=err.message}finally{button.disabled=false;$('#save-price').disabled=false;$('#quick-price').disabled=false}}
function copyQuoteText(){const text=$('#quick-quote-message').value;if(!text||!text.includes(location.origin+'/booking.html#')){msg.textContent='Prepare the quote and booking link first.';return}copyValue('Quote text',text);}
function provider(kind){try{return localStorage.getItem('trustlane-'+kind+'-provider')||''}catch{return ''}}
function setProvider(kind,value){try{localStorage.setItem('trustlane-'+kind+'-provider',value);return localStorage.getItem('trustlane-'+kind+'-provider')===value}catch{return false}}
function canChooseProvider(){return !!profile?.active&&['admin','agent'].includes(profile.role)}
function updateTextProviderStatus(){const status=$('#text-provider-status');if(!status)return;const choice=provider('text');status.textContent=choice==='ringcentral'?'RingCentral selected for this browser. Connection and SMS access are not verified. Sign in to RingCentral and confirm your account can send SMS.':choice==='zoom'?'Zoom Phone selected for this browser. Connection and SMS access are not verified. Sign in to Zoom and confirm your account has Zoom Phone and SMS enabled.':'No text provider selected on this browser. Choose one below; selection does not connect an account.';}
function showTextProviderSetup(){if(!canChooseProvider()){msg.textContent='Text provider is not set. Contact your administrator for access and setup.';return}msg.textContent='Choose a text provider for this browser.';const notice=$('#detail-message');if(!notice)return;const button=document.createElement('button');button.type='button';button.className='provider-settings-link';button.textContent='Open Communication settings';button.onclick=()=>{selectDetailTab('overview');const settings=$('#communication-settings');if(settings)settings.open=true;$('#text-provider')?.focus()};notice.append(' ',button);}
function preparedQuote(){const t=$('#quick-quote-message')?.value||'';return t.includes(location.origin+'/booking.html#')?t:''}
function openQuoteText(){const text=preparedQuote(),phone=String(selected?.phone||'').replace(/[^0-9+]/g,'');if(!text||phone.replace(/\D/g,'').length<7){msg.textContent='A prepared booking link and phone number are required.';return}const choice=provider('text');if(choice==='ringcentral'){window.open('https://app.ringcentral.com/r/sms?type=new&number='+encodeURIComponent(phone)+'&content='+encodeURIComponent(text),'_blank','noopener');msg.textContent='Review the draft in RingCentral. Sending is not confirmed.'}else if(choice==='zoom'){navigator.clipboard?.writeText(text).then(()=>{msg.textContent='Quote copied. Open Zoom Phone using the link in communication settings, enter the customer number, and paste. Sending is not confirmed.'}).catch(()=>{msg.textContent='Copy failed. Select the prepared quote text and copy it manually, then open Zoom Phone.'});if(!navigator.clipboard?.writeText)msg.textContent='Clipboard unavailable. Select and copy the prepared text, then open Zoom Phone.'}else showTextProviderSetup()}
async function openEmail(){const email=String(selected?.email||'');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){msg.textContent='A valid email address is required.';return}const choice=provider('email'),body=preparedQuote();if(!choice){msg.textContent='Choose an email provider in Communication settings first.';return}if(choice==='hostinger'){if(body){try{await navigator.clipboard.writeText(body);msg.textContent='Quote copied. Open Hostinger webmail using the link in communication settings, enter the recipient, and paste. Sending is not confirmed.'}catch{msg.textContent='Copy failed. Select the prepared quote and copy it manually, then open Hostinger webmail.'}}else msg.textContent='Open Hostinger webmail using the link in communication settings and enter the recipient.';return}const params='to='+encodeURIComponent(email)+'&su='+encodeURIComponent('Your Trustlane transportation quote')+'&body='+encodeURIComponent(body);if(choice==='gmail')window.open('https://mail.google.com/mail/?view=cm&fs=1&'+params,'_blank','noopener');else location.href='mailto:'+encodeURIComponent(email)+'?subject='+encodeURIComponent('Your Trustlane transportation quote')+'&body='+encodeURIComponent(body);msg.textContent='Review the draft in your email app. Sending is not confirmed.'}
function bindProviders(){const allowed=canChooseProvider();for(const kind of ['text','email']){const el=$('#'+kind+'-provider');el.value=provider(kind);el.disabled=!allowed;el.onchange=()=>{if(!canChooseProvider()){msg.textContent='Contact your administrator for communication setup.';return}if(!setProvider(kind,el.value)){msg.textContent='Provider preference could not be saved in this browser. Check browser storage and try again.';el.value=provider(kind)}else msg.textContent=(kind==='text'?'Text':'Email')+' preference saved on this browser. Account connection is not verified.';if(kind==='text')updateTextProviderStatus()}}updateTextProviderStatus();const retry=$('#retry-text');if(retry)retry.onclick=openQuoteText;if($('#lead-text'))$('#lead-text').onclick=()=>{selectDetailTab('overview');if(preparedQuote())openQuoteText();else if(!provider('text'))showTextProviderSetup();else msg.textContent='Enter the price and prepare the quote text with its booking link first.'};if($('#lead-email'))$('#lead-email').onclick=openEmail;}
function overviewHtml(l,notes){const name=assignedName(l);const value=v=>esc(v===null||v===undefined||v===''?'Not recorded':v);const date=Date.parse(l.created_at);const arrived=Number.isFinite(date)?new Date(date).toLocaleString():'Not recorded';const vehicle=[l.vehicle_year,l.vehicle_make,l.vehicle_model].filter(Boolean).join(' ');const statuses=['New','Assigned','Contacted','Quoted','Booked','Closed'];return `<div class="speed-grid"><section class="speed-card"><h3>Shipment</h3><div class="speed-facts"><p><b>Pickup</b><span>${value(l.pickup)}</span>${zipMarkup("pickup",l.pickup)}</p><p><b>Delivery</b><span>${value(l.delivery)}</span>${zipMarkup("delivery",l.delivery)}</p><p><b>Ship date</b><span>${value(l.preferred_date)}</span></p><p><b>Vehicle</b><span>${value(completeVehicle(l))}</span></p><p><b>Running condition</b><span>Not recorded</span></p><p><b>Transport</b><span>${value(l.transport_type)}</span></p></div><form id="quick-quote-form" class="quick-quote"><label>Customer quote $<input id="quick-price" name="quote_amount" type="number" min="0" max="9999999999" step="0.01" value="${esc(l.quote_amount??'')}" required></label><button type="submit" id="save-price">Save price</button><button type="button" id="prepare-quote">Prepare quote text + booking link</button></form><label class="quote-output">Prepared quote text<textarea id="quick-quote-message" readonly rows="3" placeholder="Save a price and prepare a quote"></textarea></label><div class="quote-actions"><button type="button" id="copy-quote-text" disabled>Copy quote text</button><button type="button" id="open-quote-text" disabled>Open text app</button></div><p class="speed-help">A quote draft and booking link are created when you prepare the text. Nothing is sent automatically.</p>${l.details?`<p class="speed-customer-detail"><b>Customer details</b> ${value(l.details)}</p>`:''}</section><section class="speed-card"><details id="communication-settings" class="communication-settings"><summary>Communication settings</summary><p id="text-provider-status" role="status"></p><label>Text provider<select id="text-provider"><option value="">Choose provider</option><option value="ringcentral">RingCentral</option><option value="zoom">Zoom Phone</option></select></label><label>Email provider<select id="email-provider"><option value="">Choose provider</option><option value="gmail">Gmail</option><option value="hostinger">Hostinger Email</option><option value="mail">Default email app</option></select></label><p>Both agents and admins can choose preferences for this browser. This does not connect a provider. Zoom and Hostinger require pasting manually.</p><button type="button" id="retry-text">Retry prepared text</button><a href="https://app.zoom.us/" target="_blank" rel="noopener">Open Zoom</a> ? <a href="https://mail.hostinger.com/" target="_blank" rel="noopener">Open Hostinger webmail</a></details><h3>Response</h3><p class="speed-arrival">Arrived ${esc(arrived)} · Assigned to ${esc(name)}</p><p id="response-timer" class="response-timer">Loading contact activity…</p><div id="response-progress" class="response-progress">Loading contact activity…</div><p class="speed-help">Calls and messages open your device apps. Record completed attempts in Contact; launching an app does not log a contact.</p><div class="speed-activity"><h4>Recent communication</h4><div id="speed-recent">Loading…</div><button type="button" data-detail-tab="contact">Record an attempt</button></div></section><section class="speed-card speed-work"><h3>Lead status</h3><form id="update"><label>Status<select name="status">${statuses.map(v=>`<option ${v===l.status?'selected':''}>${v}</option>`).join('')}</select></label><label>Closed outcome<input name="outcome" maxlength="200" value="${esc(l.closed_outcome||'')}"></label>${profile.role==='admin'?`<label>Assigned agent<select name="assignee"><option value="">Unassigned</option>${agents.filter(a=>a.active||a.user_id===l.assigned_to).map(a=>`<option value="${esc(a.user_id)}" ${a.user_id===l.assigned_to?'selected':''}>${esc(a.display_name)}</option>`).join('')}</select></label>`:''}<button class="button primary">Save status</button></form><h3>Quick note</h3><div class="speed-note">${notes.length?esc(notes[notes.length-1].body):'No notes yet.'}</div><form id="quick-note"><label><span class="visually-hidden">Add a short internal note</span><textarea name="body" required maxlength="4000" rows="2" placeholder="Add an internal note"></textarea></label><button class="button primary">Add note</button></form></section></div>`;}
async function loadContact(id){const events=await api(`/rest/v1/trustlane_contact_events?lead_id=eq.${encodeURIComponent(id)}&select=kind,outcome,details,created_at,created_by&order=created_at.desc`);if(!selected||selected.id!==id)return;contactEvents=events;contactReady=true;$('#contact-list').innerHTML=events.map(e=>`<div class="note"><strong>${esc(e.kind)} · ${esc(e.outcome)}</strong><br><small>${esc(new Date(e.created_at).toLocaleString())}</small>${e.details?`<p>${esc(e.details)}</p>`:''}</div>`).join('')||'<p class="team-empty">No contact attempts recorded.</p>';$('#response-progress').innerHTML=['Call','Text','Email'].map(k=>`<span>${k}: <b>${events.some(e=>e.kind===k||(k==='Call'&&e.kind==='Voicemail'))?'Logged':'Not logged'}</b></span>`).join('');$('#speed-recent').innerHTML=events.slice(0,2).map(e=>`<p><b>${esc(e.kind)}</b> · ${esc(e.outcome)} <small>${esc(new Date(e.created_at).toLocaleString())}</small></p>`).join('')||'<p>No attempts recorded.</p>';updateResponse();}
function contactLoadFailed(err){contactReady=false;const p=$('#response-progress'),r=$('#speed-recent'),timer=$('#response-timer');if(p)p.textContent='Activity unavailable';if(timer)timer.textContent='Response status unavailable';if(r)r.innerHTML='<p>Could not load activity.</p><button type="button" id="retry-contact">Retry</button>';const retry=$('#retry-contact');if(retry)retry.onclick=()=>loadContact(selected.id).catch(contactLoadFailed);msg.textContent=err.message||'Could not load contact activity.';}
async function addContact(e){e.preventDefault();const form=e.target,button=form.querySelector('button'),data=Object.fromEntries(new FormData(form));data.lead_id=selected.id;data.created_by=user.id;button.disabled=true;try{await api('/rest/v1/trustlane_contact_events',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(data)});form.reset();await loadContact(selected.id);msg.textContent='Contact activity recorded.'}catch(err){msg.textContent=err.message}finally{button.disabled=false}}
async function loadPayments(id){const records=await api(`/rest/v1/trustlane_payment_records?lead_id=eq.${encodeURIComponent(id)}&select=id,kind,amount,transaction_date,reference,notes,created_at,voided_at,void_reason&order=created_at.desc`);$('#payment-list').innerHTML=records.map(r=>`<div class="note"><strong>${esc(r.kind)} · $${esc(Number(r.amount).toFixed(2))}${r.voided_at?' · VOID':''}</strong><br><small>${esc(r.transaction_date)}${r.reference?' · Ref '+esc(r.reference):''}</small>${r.notes?`<p>${esc(r.notes)}</p>`:''}${r.voided_at?`<p>Voided: ${esc(r.void_reason)}</p>`:`<details><summary>Void incorrect record</summary><form data-void-payment="${esc(r.id)}"><label>Reason<input name="reason" required maxlength="500"></label><button type="submit">Void record</button></form></details>`}</div>`).join('')||'<p class="team-empty">No transactions recorded.</p>';}
async function voidPayment(e){const form=e.target.closest('[data-void-payment]');if(!form)return;e.preventDefault();const button=form.querySelector('button');button.disabled=true;try{await api('/rest/v1/rpc/trustlane_void_payment_record',{method:'POST',body:JSON.stringify({p_id:form.dataset.voidPayment,p_reason:new FormData(form).get('reason')})});await loadPayments(selected.id);msg.textContent='Record voided. No money was moved.'}catch(err){msg.textContent=err.message}finally{button.disabled=false}}
async function addPayment(e){e.preventDefault();const form=e.target,button=form.querySelector('button'),data=Object.fromEntries(new FormData(form));data.amount=Number(data.amount);data.lead_id=selected.id;data.created_by=user.id;button.disabled=true;try{await api('/rest/v1/trustlane_payment_records',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(data)});form.reset();await loadPayments(selected.id);msg.textContent='Transaction record added; no payment was processed.'}catch(err){msg.textContent=err.message}finally{button.disabled=false}}
let quoteDrafts=[];
function vehicleFields(v={}){const fields=[['year','Year','number'],['make','Make','text'],['model','Model','text'],['vin','VIN','text'],['vehicle_type','Vehicle type','text'],['color','Color','text'],['condition','Condition','text'],['carrier_notes','Carrier notes','text']];return `<div class="working-grid">${fields.map(([key,label,type])=>`<label>${esc(label)}<input name="${key}" type="${type}" value="${esc(v[key]??'')}" ${['make','model'].includes(key)?'required maxlength="80"':''} ${key==='year'?'min="1886" max="2100"':''} ${key==='vin'?'maxlength="17"':''} ${['vehicle_type','color'].includes(key)?'maxlength="80"':''} ${key==='condition'?'maxlength="300"':''} ${key==='carrier_notes'?'maxlength="2000"':''}></label>`).join('')}<label>Keys available<select name="keys_available">${['','Yes','No','Unknown'].map(x=>`<option value="${x}" ${x===(v.keys_available||'')?'selected':''}>${x||'Not set'}</option>`).join('')}</select></label></div>`;}
async function loadVehicles(id){const vehicles=await api(`/rest/v1/trustlane_vehicles?lead_id=eq.${encodeURIComponent(id)}&select=*&order=created_at.asc`);$('#vehicle-list').innerHTML=vehicles.map(v=>`<details class="vehicle-card"><summary>${esc([v.year,v.make,v.model].filter(Boolean).join(' '))} ${v.active?'':'(archived)'}</summary><form data-vehicle-form="${esc(v.id)}">${vehicleFields(v)}<button class="button primary">Save vehicle</button> <button type="button" data-archive="${esc(v.id)}" data-active="${v.active}">${v.active?'Archive':'Restore'}</button></form></details>`).join('')||'<p class="team-empty">No additional vehicles. The primary vehicle is listed above.</p>';}
async function addVehicle(e){e.preventDefault();const form=e.target,button=form.querySelector('button'),data=Object.fromEntries(new FormData(form));data.year=data.year?Number(data.year):null;data.lead_id=selected.id;data.created_by=user.id;button.disabled=true;try{await api('/rest/v1/trustlane_vehicles',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(data)});form.reset();await loadVehicles(selected.id);msg.textContent='Vehicle added.'}catch(err){msg.textContent=err.message}finally{button.disabled=false}}
async function editVehicle(e){const form=e.target.closest('[data-vehicle-form]');if(!form)return;e.preventDefault();const data=Object.fromEntries(new FormData(form));data.year=data.year?Number(data.year):null;try{const rows=await api('/rest/v1/trustlane_vehicles?id=eq.'+encodeURIComponent(form.dataset.vehicleForm),{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify(data)});if(!Array.isArray(rows)||rows.length!==1)throw Error('Vehicle could not be updated.');await loadVehicles(selected.id);msg.textContent='Vehicle saved.'}catch(err){msg.textContent=err.message}}
async function archiveVehicle(e){const b=e.target.closest('[data-archive]');if(!b)return;try{const rows=await api('/rest/v1/trustlane_vehicles?id=eq.'+encodeURIComponent(b.dataset.archive),{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({active:b.dataset.active!=='true'})});if(!Array.isArray(rows)||rows.length!==1)throw Error('Vehicle could not be updated.');await loadVehicles(selected.id);msg.textContent='Vehicle updated.'}catch(err){msg.textContent=err.message}}
const quoteVehicles=s=>[[s.vehicle_year,s.vehicle_make,s.vehicle_model].filter(Boolean).join(' '),...(s.additional_vehicles||[]).map(v=>[v.year,v.make,v.model].filter(Boolean).join(' '))].filter(Boolean).join('; ');
const defaultTemplates=[{id:'intro',title:'Introduction',body:'Hello {{name}},\n\nThank you for contacting Trustlane Transportation about your vehicle transport request. Please let us know a convenient time to discuss the details.\n\nTrustlane Transportation'},{id:'quote',title:'Quote details',body:'Hello {{name}},\n\nHere are the transport details for {{vehicle}} from {{pickup}} to {{delivery}}.\nQuote amount: {{quote}}\nPreferred shipping date: {{date}}\n\nPlease let us know if you have any questions.\n\nTrustlane Transportation'},{id:'followup',title:'Follow-up',body:'Hello {{name}},\n\nI am following up about your vehicle transport request from {{pickup}} to {{delivery}}. Please let us know if you would like to discuss the next steps.\n\nTrustlane Transportation'}];
function fillTemplate(body,l){const v={name:l.name||'',pickup:l.pickup||'',delivery:l.delivery||'',vehicle:[l.vehicle_year,l.vehicle_make,l.vehicle_model].filter(Boolean).join(' '),quote:l.quote_amount==null?'Please ask for a quote':'$'+Number(l.quote_amount).toFixed(2),date:l.preferred_date||'Not set'};return body.replace(/\{\{(name|pickup|delivery|vehicle|quote|date)\}\}/g,(_,k)=>v[k]);}
async function openTemplates(){const d=$('#template-dialog'),choice=$('#template-choice'),body=$('#template-body'),title=$('#template-name'),notice=$('#template-notice');let saved=[];const report=e=>notice.textContent=e.message||String(e);const reload=async id=>{saved=await api('/rest/v1/trustlane_message_templates?select=id,title,body&order=title.asc');choice.innerHTML='<option value="">New template</option>'+defaultTemplates.map(t=>`<option value="default:${esc(t.id)}">${esc(t.title)} (built-in)</option>`).join('')+saved.map(t=>`<option value="${esc(t.id)}">${esc(t.title)}</option>`).join('');choice.value=id||'default:intro';show();};const show=()=>{const val=choice.value;const t=val.startsWith('default:')?defaultTemplates.find(x=>'default:'+x.id===val):saved.find(x=>x.id===val);title.value=t?.title||'';body.value=t?.body||'';$('#template-delete').disabled=!val||val.startsWith('default:');notice.textContent=val.startsWith('default:')?'Saving a built-in template creates your personal copy.':'';};choice.onchange=show;$('#template-new').onclick=()=>{choice.value='';show();title.focus()};$('#template-save').onclick=async()=>{try{const name=title.value.trim(),text=body.value.trim();if(!name||!text)throw Error('Enter a template name and message.');const id=choice.value;const editing=id&&!id.startsWith('default:');await api('/rest/v1/trustlane_message_templates'+(editing?'?id=eq.'+encodeURIComponent(id):''),{method:editing?'PATCH':'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({title:name,body:text,...(!editing?{owner_id:user.id}:{})})}).then(async rows=>{await reload(rows[0].id);notice.textContent='Template saved.'});}catch(e){report(e)}};$('#template-delete').onclick=async()=>{const id=choice.value;const item=saved.find(t=>t.id===id);if(!item||!window.confirm('Delete template '+item.title+'? This cannot be undone.'))return;try{const rows=await api('/rest/v1/trustlane_message_templates?id=eq.'+encodeURIComponent(id),{method:'DELETE',headers:{Prefer:'return=representation'}});if(!rows?.length)throw Error('Template could not be deleted. Refresh and try again.');await reload();notice.textContent='Template deleted.'}catch(e){report(e)}};$('#template-copy').onclick=async()=>{try{await navigator.clipboard.writeText(fillTemplate(body.value,selected));notice.textContent='Copied. Paste it into your message.'}catch{notice.textContent='Copy is unavailable in this browser.'}};$('#template-email').onclick=()=>{window.location.href=`mailto:${encodeURIComponent(selected.email||'')}?subject=${encodeURIComponent('Vehicle transport request')}&body=${encodeURIComponent(fillTemplate(body.value,selected))}`};d.showModal();try{await reload()}catch(e){report(e)}}
function quoteEmail(q,lead){const s=q.snapshot;const lines=[`Hello ${s.name},`,'','Here are the vehicle transport details we discussed:',`Pickup: ${s.pickup}`,`Delivery: ${s.delivery}`,`Vehicle(s): ${quoteVehicles(s)}`,`Preferred shipping date: ${s.preferred_date}`,...(s.transport_type?[`Transport type: ${s.transport_type}`]:[]),`Quote amount: $${Number(s.quote_amount).toFixed(2)}`,...(s.quote_expires_on?[`Quote expiration: ${s.quote_expires_on}`]:[]),...(s.special_terms?[`Terms: ${s.special_terms}`]:[]),'','Trustlane Transportation'];return `mailto:${encodeURIComponent(lead.email||'')}?subject=${encodeURIComponent('Vehicle transport quote')}&body=${encodeURIComponent(lines.join('\n'))}`;}
async function loadQuotes(id){quoteDrafts=await api(`/rest/v1/trustlane_quote_drafts?lead_id=eq.${encodeURIComponent(id)}&select=id,created_at,snapshot&order=created_at.desc`);const lead=leads.find(l=>l.id===id);$('#quote-list').innerHTML=quoteDrafts.map(q=>`<div class="task-row"><span><strong>Draft quote · $${esc(Number(q.snapshot.quote_amount).toFixed(2))}</strong><small>${esc(new Date(q.created_at).toLocaleString())}</small></span><span><button type="button" data-quote="${esc(q.id)}">Download</button>${lead?.email?` <a href="${esc(quoteEmail(q,lead))}">Open email app</a>`:''}</span></div>`).join('')||'<p class="team-empty">No quote drafts yet.</p>';}
async function createQuote(e){e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await api('/rest/v1/rpc/trustlane_create_quote_draft',{method:'POST',body:JSON.stringify({p_lead_id:selected.id})});await loadQuotes(selected.id);await loadSigning(selected.id);await loadOrder(selected.id);msg.textContent='Quote draft created. It has not been sent.'}catch(err){msg.textContent=err.message}finally{button.disabled=false}}
async function loadOrder(id){const orders=await api(`/rest/v1/trustlane_orders?lead_id=eq.${encodeURIComponent(id)}&select=id,quote_id,stage,confirmation_note,created_at,updated_at`);const order=orders[0];if(order){$('#order-content').innerHTML=`<p><strong>Order recorded</strong> · ${esc(new Date(order.created_at).toLocaleString())}</p><p>Customer agreement recorded by the team: ${esc(order.confirmation_note)}</p><form id="order-stage-form"><label>Shipment stage<select name="stage">${['Awaiting dispatch','Carrier assigned','Dispatched','Picked up','In transit','Delivered','Cancelled'].map(s=>`<option ${s===order.stage?'selected':''}>${esc(s)}</option>`).join('')}</select></label><button class="button primary">Save order stage</button></form><h4>Invoices</h4><p>Creates a document from this order’s saved quote. It does not collect payment.</p><form id="invoice-form"><label>Due date (optional)<input name="due_on" type="date"></label><button class="button primary">Create invoice</button></form><div id="invoice-list"></div><h4>Order stage history</h4><div id="order-history"></div>`;$('#order-stage-form').onsubmit=e=>updateOrder(e,order.id);$('#invoice-form').onsubmit=e=>createInvoice(e,order.id);$('#invoice-list').onclick=downloadInvoice;await loadInvoices(order.id);await loadOrderHistory(order.id);return}$('#order-content').innerHTML=quoteDrafts.length?`<p>Only record an order after the customer has agreed outside this portal. This does not dispatch a carrier, collect a signature, or process a payment.</p><form id="order-create-form"><label>Agreed quote<select name="quote_id" required>${quoteDrafts.map(q=>`<option value="${esc(q.id)}">$${esc(Number(q.snapshot.quote_amount).toFixed(2))} · ${esc(new Date(q.created_at).toLocaleString())}</option>`).join('')}</select></label><label>How was the customer's agreement confirmed?<textarea name="confirmation_note" minlength="5" maxlength="1000" required></textarea></label><label><input name="confirmed" type="checkbox" required> I have confirmed the customer agreed to this quote.</label><button class="button primary">Record confirmed order</button></form>`:'<p>Create a quote draft first. A draft does not automatically become an order.</p>';if(quoteDrafts.length)$('#order-create-form').onsubmit=createOrder;}
async function createOrder(e){e.preventDefault();const form=e.target,button=form.querySelector('button'),f=new FormData(form);button.disabled=true;const id=selected.id;try{await api('/rest/v1/rpc/trustlane_record_manual_order',{method:'POST',body:JSON.stringify({p_lead_id:id,p_quote_id:f.get('quote_id'),p_confirmation_note:f.get('confirmation_note'),p_confirmed:f.get('confirmed')==='on'})});await load();await detail(id);msg.textContent='Order recorded from customer agreement.'}catch(err){msg.textContent=err.message}finally{button.disabled=false}}
async function updateOrder(e,id){e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await api('/rest/v1/rpc/trustlane_update_order_stage',{method:'POST',body:JSON.stringify({p_order_id:id,p_stage:new FormData(e.target).get('stage')})});await loadOrder(selected.id);msg.textContent='Order stage saved.'}catch(err){msg.textContent=err.message}finally{button.disabled=false}}
async function loadOrderHistory(id){const events=await api(`/rest/v1/trustlane_order_events?order_id=eq.${encodeURIComponent(id)}&select=created_at,previous_stage,new_stage&order=created_at.desc`);$('#order-history').innerHTML=events.map(e=>`<div class="note"><strong>${esc(e.previous_stage?e.previous_stage+' → ':'')}${esc(e.new_stage)}</strong><br><small>${esc(new Date(e.created_at).toLocaleString())}</small></div>`).join('')||'<p class="team-empty">No order history yet.</p>';}
let signatures=[];
async function loadSigning(id){const lead=leads.find(l=>l.id===id);signatures=await api(`/rest/v1/trustlane_signatures?lead_id=eq.${encodeURIComponent(id)}&select=id,signed_name,signed_at,signed_version,agreement_body,signed_snapshot,signer_ip&order=signed_at.desc`);const state=lead.signed_contract_version==null?'No signed agreement yet.':String(lead.signed_contract_version)===String(lead.contract_version)?'Agreement signed for the current shipment details.':'Shipment details changed after signing. A new agreement must be signed.';$('#booking-status').textContent=state;$('#signature-list').innerHTML=signatures.map(s=>`<div class="task-row"><span><strong>Signed by ${esc(s.signed_name)}</strong><small>${esc(new Date(s.signed_at).toLocaleString())} - Signing IP: ${esc(s.signer_ip||"Not recorded")}</small></span><button type="button" data-signature="${esc(s.id)}">Download agreement</button></div>`).join('')||'<p class="team-empty">No signatures recorded.</p>';$('#booking-issue').innerHTML=quoteDrafts.length?`<form id="booking-issue-form"><label>Quote for booking<select name="quote_id" required>${quoteDrafts.map(q=>`<option value="${esc(q.id)}">$${esc(Number(q.snapshot.quote_amount).toFixed(2))} · ${esc(new Date(q.created_at).toLocaleString())}</option>`).join('')}</select></label><button class="button primary">Generate booking link</button></form><p>Links expire after seven days and can be used once. Generating a link does not send it.</p><label>Booking link<input id="booking-link" readonly placeholder="Generate a link to display it"></label><button type="button" id="copy-booking">Copy link</button>`:'<p>Create a quote draft before generating a booking link.</p>';if(quoteDrafts.length){$('#booking-issue-form').onsubmit=issueBooking;$('#copy-booking').onclick=copyBooking;}}
async function issueBooking(e){e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const bytes=crypto.getRandomValues(new Uint8Array(32)),token=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(token));const hash=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');await api('/rest/v1/rpc/trustlane_issue_booking_link',{method:'POST',body:JSON.stringify({p_lead_id:selected.id,p_quote_id:new FormData(e.target).get('quote_id'),p_token_hash:hash})});$('#booking-link').value=location.origin+'/booking.html#'+token;msg.textContent='Booking link created. It has not been sent.'}catch(err){msg.textContent=err.message}finally{button.disabled=false}}
async function copyBooking(){const value=$('#booking-link').value;if(!value){msg.textContent='Generate a booking link first.';return}try{await navigator.clipboard.writeText(value);msg.textContent='Booking link copied.'}catch{msg.textContent='Select and copy the booking link from the field.'}}
function downloadSignature(e){const b=e.target.closest('[data-signature]');if(!b)return;const s=signatures.find(x=>x.id===b.dataset.signature);if(!s)return;const q=s.signed_snapshot;const rows=[['Customer',q.name],['Pickup',q.pickup],['Pickup address',q.pickup_address],['Delivery',q.delivery],['Delivery address',q.delivery_address],['Vehicle(s)',quoteVehicles(q)],['Quote amount','$'+Number(q.quote_amount).toFixed(2)],['Signed by',s.signed_name],['Signed at',new Date(s.signed_at).toLocaleString()],['Signing IP',s.signer_ip||'Not recorded']];const doc=`<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Signed agreement</title><style>body{font:16px/1.5 system-ui,sans-serif;max-width:720px;margin:3rem auto;padding:0 1rem;color:#152b32}dl{display:grid;grid-template-columns:1fr 2fr;gap:1rem}dt{font-weight:bold}dd{margin:0;white-space:pre-wrap}.terms{white-space:pre-wrap}</style></head><body><h1>Trustlane Transportation</h1><h2>Signed agreement</h2><dl>${rows.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><h2>Agreement terms</h2><div class="terms">${esc(s.agreement_body)}</div></body></html>`;const url=URL.createObjectURL(new Blob([doc],{type:'text/html;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='trustlane-agreement-'+s.id+'.html';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let orderInvoices=[];
async function loadInvoices(orderId){orderInvoices=await api(`/rest/v1/trustlane_invoices?order_id=eq.${encodeURIComponent(orderId)}&select=id,issued_on,due_on,created_at,snapshot&order=created_at.desc`);$('#invoice-list').innerHTML=orderInvoices.map(i=>`<div class="task-row"><span><strong>Invoice ${esc(i.id.slice(0,8).toUpperCase())}</strong><small>Issued ${esc(i.issued_on)} · $${esc(Number(i.snapshot.quote_amount).toFixed(2))}</small></span><button type="button" data-invoice="${esc(i.id)}">Download</button></div>`).join('')||'<p class="team-empty">No invoices yet.</p>';}
async function createInvoice(e,id){e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await api('/rest/v1/rpc/trustlane_create_invoice',{method:'POST',body:JSON.stringify({p_order_id:id,p_due_on:new FormData(e.target).get('due_on')||null})});await loadInvoices(id);msg.textContent='Invoice created; no payment was processed.'}catch(err){msg.textContent=err.message}finally{button.disabled=false}}
function downloadInvoice(e){const b=e.target.closest('[data-invoice]');if(!b)return;const i=orderInvoices.find(x=>x.id===b.dataset.invoice);if(!i)return;const s=i.snapshot;const rows=[['Invoice',i.id],['Issued',i.issued_on],['Due',i.due_on],['Customer',s.name],['Pickup',s.pickup],['Delivery',s.delivery],['Vehicle(s)',quoteVehicles(s)],['Total','$'+Number(s.quote_amount).toFixed(2)]].filter(([,v])=>v!==null&&v!==undefined&&v!=='');const doc=`<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Trustlane invoice</title><style>body{font:16px/1.5 system-ui,sans-serif;max-width:720px;margin:3rem auto;padding:0 1rem;color:#152b32}h1{font-family:Georgia,serif}dl{display:grid;grid-template-columns:1fr 2fr;gap:1rem}dt{font-weight:bold}dd{margin:0;white-space:pre-wrap}</style></head><body><h1>Trustlane Transportation</h1><h2>Invoice</h2><dl>${rows.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl></body></html>`;const url=URL.createObjectURL(new Blob([doc],{type:'text/html;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='trustlane-invoice-'+i.id+'.html';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadQuote(e){const button=e.target.closest('[data-quote]');if(!button)return;const q=quoteDrafts.find(item=>item.id===button.dataset.quote);if(!q)return;const s=q.snapshot;const rows=[['Customer',s.name],['Pickup',s.pickup],['Delivery',s.delivery],['Vehicle(s)',quoteVehicles(s)],['Preferred shipping date',s.preferred_date],['Transport type',s.transport_type],['Quote amount','$'+Number(s.quote_amount).toFixed(2)],['Quote expiration',s.quote_expires_on],['Special terms',s.special_terms]].filter(([,v])=>v!==null&&v!==undefined&&v!=='');const doc=`<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Trustlane quote draft</title><style>body{font:16px/1.5 system-ui,sans-serif;max-width:720px;margin:3rem auto;padding:0 1rem;color:#152b32}h1{font-family:Georgia,serif}dl{display:grid;grid-template-columns:1fr 2fr;gap:1rem}dt{font-weight:bold}dd{margin:0;white-space:pre-wrap}</style></head><body><h1>Trustlane Transportation</h1><h2>Quote draft</h2><p>Prepared ${esc(new Date(q.created_at).toLocaleDateString())}</p><dl>${rows.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl></body></html>`;const url=URL.createObjectURL(new Blob([doc],{type:'text/html;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='trustlane-quote-'+q.id+'.html';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function render(){const q=$('#search').value.toLowerCase().trim(),f=$('#filter').value,origin=$('#pickup-filter').value.toLowerCase().trim(),destination=$('#delivery-filter').value.toLowerCase().trim();const view=$('#pipeline').value||'all';const views=[['all','All work',()=>true],['leads','Leads',l=>['New','Assigned','Contacted'].includes(l.status)],['quotes','Quotes',l=>l.status==='Quoted'],['orders','Orders',l=>l.status==='Booked'],['closed','Closed',l=>l.status==='Closed']];const active=views.find(v=>v[0]===view)||views[0];$('#pipeline-nav').innerHTML=views.map(([key,label,match])=>`<button type="button" data-view="${key}" aria-pressed="${key===active[0]}">${label} <span>${leads.filter(match).length}</span></button>`).join('');$('#inbox-title').textContent=active[1];const matching=leads.filter(l=>active[2](l)&&(!f||l.status===f)&&[l.name,l.email,l.phone,l.pickup,l.delivery,l.vehicle_make,l.vehicle_model].join(' ').toLowerCase().includes(q)&&String(l.pickup||'').toLowerCase().includes(origin)&&String(l.delivery||'').toLowerCase().includes(destination));$('#lead-count').textContent=matching.length+' shown';$('#leads').innerHTML=matching.map(l=>`<button class="lead-button" data-id="${esc(l.id)}"><b>${esc(l.name)}</b><span>${esc(l.pickup)} → ${esc(l.delivery)}</span><span>${esc([l.vehicle_year,l.vehicle_make,l.vehicle_model].filter(Boolean).join(' '))}</span><span>${esc(l.status)} · ${esc(new Date(l.created_at).toLocaleDateString())}</span></button>`).join('')||'<p class="empty-list">No records in this view match your filters.</p>';}
async function detail(id){if(selected?.id!==id)detailTab="overview";selected=leads.find(l=>l.id===id);if(!selected)return;const l=selected;stopResponseTimer();contactEvents=[];contactReady=false;const notes=await api(`/rest/v1/trustlane_notes?lead_id=eq.${encodeURIComponent(id)}&select=*&order=created_at.asc`);const phone=String(l.phone||'').replace(/[^0-9+]/g,'');const email=String(l.email||'');$('#detail').innerHTML=`<div class="lead-detail-heading"><div><p class="eyebrow">LEAD DETAILS</p><h2>${esc(l.name)}</h2></div><span class="count-badge">${esc(l.status)}</span>${l.signed_contract_version!=null&&String(l.signed_contract_version)!==String(l.contract_version)?`<span class="contract-alert">Agreement needs re-signing</span>`:""}<button type="button" id="detail-close" aria-label="Close lead workspace">Close</button></div><div id="detail-message" class="detail-message" role="status" aria-live="polite"></div><div class="contact-summary"><span>Phone: ${esc(l.phone||"Not recorded")}</span><span>Email: ${esc(l.email||"Not recorded")}</span><span>Assigned: ${esc(assignedName(l))}</span><span>Arrived: ${Number.isFinite(Date.parse(l.created_at))?esc(new Date(l.created_at).toLocaleString()):"Not recorded"}</span></div><div class="contact-actions speed-actions">${phone.replace(/[^0-9]/g,'').length>=7?`<a href="tel:${esc(phone)}" aria-label="Call ${esc(l.name)}">Call <small>Open phone app</small></a><button type="button" id="lead-text" aria-label="Text ${esc(l.name)}">Text <small>Prepare quote</small></button>`:'<button type="button" disabled title="A valid phone number is needed">Call <small>Phone unavailable</small></button><button type="button" disabled title="A valid phone number is needed">Text <small>Phone unavailable</small></button>'}${/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)?`<button type="button" id="lead-email" aria-label="Email ${esc(l.name)}">Email <small>Open composer</small></button>`:'<button type="button" disabled title="A valid email address is needed">Email <small>Email unavailable</small></button>'}<button type="button" id="open-templates">Text templates</button></div><dialog id="template-dialog" aria-labelledby="template-title"><div class="template-heading"><h3 id="template-title">Text templates</h3><form method="dialog"><button aria-label="Close templates">Close</button></form></div><p>Choose a starting message, edit it, and copy it or open your email app. Messages are not sent automatically.</p><label>Template<select id="template-choice"><option value="intro">Introduction</option><option value="quote">Quote details</option><option value="followup">Follow-up</option></select></label><label>Template name<input id="template-name" maxlength="120"></label><p>Use {{name}}, {{pickup}}, {{delivery}}, {{vehicle}}, {{quote}}, and {{date}} to insert lead details.</p><label>Message<textarea id="template-body" rows="10" maxlength="5000"></textarea></label><div class="template-actions"><button type="button" id="template-new">New template</button><button type="button" id="template-save">Save template</button><button type="button" id="template-delete">Delete template</button><button type="button" id="template-copy">Copy message</button><button type="button" id="template-email">Open email app</button></div><p id="template-notice" role="status"></p></dialog><div class="detail-nav" role="group" aria-label="Lead workspace sections"><button type="button" data-detail-tab="overview" aria-pressed="false">Overview</button><button type="button" data-detail-tab="shipment" aria-pressed="false">Shipment</button><button type="button" data-detail-tab="vehicles" aria-pressed="false">Vehicles</button><button type="button" data-detail-tab="quotes" aria-pressed="false">Quotes</button><button type="button" data-detail-tab="booking" aria-pressed="false">Booking</button><button type="button" data-detail-tab="order" aria-pressed="false">Order</button><button type="button" data-detail-tab="activity" aria-pressed="false">Timeline</button><button type="button" data-detail-tab="payment" aria-pressed="false">Payments</button><button type="button" data-detail-tab="contact" aria-pressed="false">Contact</button><button type="button" data-detail-tab="tasks" aria-pressed="false">Tasks</button><button type="button" data-detail-tab="notes" aria-pressed="false">Notes</button></div><div class="detail-body"><section data-detail-panel="overview">${overviewHtml(l,notes)}</section><section id="working-details" data-detail-panel="shipment"></section><section class="followup-panel" data-detail-panel="vehicles" aria-labelledby="vehicles-heading"><h3 id="vehicles-heading">Additional vehicles</h3><p>The original vehicle is shown in the shipment details. Add any other vehicles here.</p><div id="vehicle-list"></div><details><summary>Add another vehicle</summary><form id="vehicle-add"></form></details></section><section class="followup-panel" data-detail-panel="quotes" aria-labelledby="quote-heading"><h3 id="quote-heading">Quote drafts</h3><p>Save shipment details and a customer amount first. Drafts are not sent automatically.</p><form id="quote-form"><button class="button primary">Create quote draft</button></form><div id="quote-list"></div></section><section class="followup-panel" data-detail-panel="booking" aria-labelledby="booking-heading"><h3 id="booking-heading">Booking and agreement</h3><p id="booking-status"></p><div id="booking-issue"></div><h4>Signature history</h4><div id="signature-list"></div></section><section class="followup-panel" data-detail-panel="order" aria-labelledby="order-heading"><h3 id="order-heading">Order</h3><div id="order-content"></div></section><section class="followup-panel" data-detail-panel="activity" aria-labelledby="activity-heading"><h3 id="activity-heading">Activity history</h3><div id="activity-list"></div></section><section class="followup-panel" data-detail-panel="payment" aria-labelledby="payment-heading"><h3 id="payment-heading">Payment records</h3><p>Record transactions already handled outside this portal. This does not collect or refund money. Do not enter card or bank details.</p><div id="payment-list"></div><form id="payment-form"><label>Transaction type<select name="kind"><option>Payment</option><option>Refund</option><option>Chargeback</option></select></label><label>Amount<input name="amount" type="number" min="0.01" max="9999999999" step="0.01" required></label><label>Transaction date<input name="transaction_date" type="date" required></label><label>Reference<input name="reference" maxlength="120"></label><label>Notes<textarea name="notes" maxlength="1000"></textarea></label><button class="button primary">Record transaction</button></form></section><section class="followup-panel" data-detail-panel="contact" aria-labelledby="contact-heading"><h3 id="contact-heading">Contact history</h3><p>Record a completed contact attempt. This does not place a call or send a message.</p><div id="contact-list"></div><form id="contact-form"><label>Contact type<select name="kind"><option>Call</option><option>Email</option><option>Text</option><option>Voicemail</option><option>Other</option></select></label><label>Outcome<input name="outcome" required maxlength="160" placeholder="Reached customer, no answer…"></label><label>Details<textarea name="details" maxlength="2000"></textarea></label><button class="button primary">Record contact</button></form></section><section class="followup-panel" data-detail-panel="tasks" aria-labelledby="task-heading"><h3 id="task-heading">Follow-up tasks</h3><div id="task-list"></div><form id="task-form"><label>Task<input name="title" required maxlength="300" placeholder="Call customer, check availability…"></label><label>Due date<input name="due_on" type="date"></label><button class="button primary">Add task</button></form></section><section data-detail-panel="notes"><h3 id="notes-heading">Internal notes</h3>${notes.map(n=>`<div class="note">${esc(n.body)}<br><small>${esc(new Date(n.created_at).toLocaleString())}</small></div>`).join('')||'<p class="team-empty">No notes yet.</p>'}<form id="note"><label>Add a note<textarea name="body" required maxlength="4000"></textarea></label><button class="button primary">Add note</button></form></section></div>`;$("#detail").classList.add("is-open");$("#detail").onclick=e=>{if(e.target.closest("#detail-close")){closeDetail();return}const b=e.target.closest("[data-detail-tab]");if(b)selectDetailTab(b.dataset.detailTab)};selectDetailTab(detailTab);$('#open-templates').onclick=openTemplates;renderWork(l);$('#vehicle-add').innerHTML=vehicleFields()+'<button class="button primary">Add vehicle</button>';if(typeof attachVehicleLookup==='function')attachVehicleLookup($('#vehicle-add'));$('#vehicle-add').onsubmit=addVehicle;$('#vehicle-list').onsubmit=editVehicle;$('#vehicle-list').onclick=archiveVehicle;$('#payment-form').onsubmit=addPayment;$('#payment-list').onsubmit=voidPayment;$('#contact-form').onsubmit=addContact;$('#quote-form').onsubmit=createQuote;$('#quote-list').onclick=downloadQuote;$('#signature-list').onclick=downloadSignature;$('#update').onsubmit=update;$('#note').onsubmit=addNote;$('#quick-note').onsubmit=addNote;bindProviders();bindCopyButtons(l);lookupLocation(l,'pickup');lookupLocation(l,'delivery');$('#quick-quote-form').onsubmit=saveQuickQuote;$('#prepare-quote').onclick=prepareQuoteText;$('#copy-quote-text').onclick=copyQuoteText;$('#open-quote-text').onclick=openQuoteText;$('#quick-price').oninput=()=>{$('#quick-quote-message').value='';$('#copy-quote-text').disabled=true;$('#open-quote-text').disabled=true};responseTimer=setInterval(updateResponse,1000);$('#task-form').onsubmit=addTask;$('#task-list').onclick=toggleTask;await loadContact(id).catch(contactLoadFailed);await loadTasks(id);await loadActivity(id);await loadVehicles(id);await loadPayments(id);await loadQuotes(id);await loadSigning(id);await loadOrder(id);}
async function loadTasks(id){const tasks=await api(`/rest/v1/trustlane_tasks?lead_id=eq.${encodeURIComponent(id)}&select=id,title,due_on,completed&order=created_at.desc`);$('#task-list').innerHTML=tasks.map(t=>`<div class="task-row"><span><strong>${esc(t.title)}</strong><small>${t.due_on?'Due '+esc(t.due_on):'No due date'} · ${t.completed?'Completed':'Open'}</small></span><button type="button" data-task="${esc(t.id)}" data-completed="${t.completed}">${t.completed?'Reopen':'Complete'}</button></div>`).join('')||'<p class="team-empty">No follow-up tasks yet.</p>';}
async function addTask(e){e.preventDefault();const f=new FormData(e.target);try{await api('/rest/v1/trustlane_tasks',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({lead_id:selected.id,created_by:user.id,title:String(f.get('title')).trim(),due_on:f.get('due_on')||null})});e.target.reset();await loadTasks(selected.id);await loadOverview();msg.textContent='Task added.'}catch(err){msg.textContent=err.message}}
async function toggleTask(e){const b=e.target.closest('[data-task]');if(!b)return;try{await api('/rest/v1/trustlane_tasks?id=eq.'+encodeURIComponent(b.dataset.task),{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({completed:b.dataset.completed!=='true'})});await loadTasks(selected.id);await loadOverview();msg.textContent='Task updated.'}catch(err){msg.textContent=err.message}}
async function update(e){e.preventDefault();let v=new FormData(e.target);try{await api('/rest/v1/rpc/trustlane_update_lead',{method:'POST',body:JSON.stringify({p_id:selected.id,p_status:v.get('status'),p_outcome:v.get('outcome'),p_assignee:v.get('assignee')||null,p_change_assignment:profile.role==='admin'})});await load();await detail(selected.id);msg.textContent='Lead updated.'}catch(err){msg.textContent=err.message}}
async function addNote(e){e.preventDefault();try{await api('/rest/v1/trustlane_notes',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({lead_id:selected.id,author_id:user.id,body:new FormData(e.target).get('body')})});await detail(selected.id);msg.textContent='Note added.'}catch(err){msg.textContent=err.message}}
$('#login-form').onsubmit=async e=>{e.preventDefault();msg.textContent='Signing in…';try{if(!config.supabaseUrl||!config.supabaseAnonKey)throw Error('Portal configuration is incomplete.');const form=new FormData(e.target);const d=await api('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:form.get('email'),password:form.get('password')})});acceptSession(d,form.get('remember')==='on');await load();e.target.reset();msg.textContent=''}catch(err){clearSession();token=null;msg.textContent=err.message}};
$('#leads').onclick=e=>{const b=e.target.closest('[data-id]');if(b)detail(b.dataset.id).catch(err=>msg.textContent=err.message)};$('#pipeline').onchange=render;$('#search').oninput=render;$('#filter').onchange=render;$('#logout').onclick=async()=>{stopResponseTimer();clearSession();try{await api('/auth/v1/logout',{method:'POST'})}catch{} token=null;user=null;profile=null;leads=[];agents=[];selected=null;$('#detail').classList.remove('is-open');$('#dashboard').hidden=true;$('#login').hidden=false;$('#detail').textContent='Select a lead to view its details.';msg.textContent='Signed out.'};
$('#task-overview').onclick=e=>{const b=e.target.closest('[data-lead]');if(b)detail(b.dataset.lead).catch(err=>msg.textContent=err.message)};
$('#detail').onkeydown=e=>{if(e.key==='Escape'&&selected){e.preventDefault();closeDetail();}};
$('#pipeline-nav').onclick=e=>{const b=e.target.closest('[data-view]');if(!b)return;$('#pipeline').value=b.dataset.view;$('#filter').value='';render()};
$('#pickup-filter').oninput=render;$('#delivery-filter').oninput=render;
$('#manual-lead-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;try{const id=await api('/rest/v1/rpc/trustlane_create_manual_lead',{method:'POST',body:JSON.stringify({p_lead:Object.fromEntries(new FormData(form))})});if(typeof id!=='string')throw Error('Lead creation could not be confirmed.');form.reset();await load();await detail(id);msg.textContent='Lead added.'}catch(err){msg.textContent=err.message}finally{button.disabled=false}};
$('#refresh-leads').onclick=async()=>{const id=selected?.id;try{await load();if(id&&leads.some(l=>l.id===id))await detail(id);msg.textContent='Leads refreshed.'}catch(err){msg.textContent=err.message}};
const authHash=new URLSearchParams(location.hash.slice(1)); const inviteToken=authHash.get('access_token'); if(inviteToken) history.replaceState(null,'',location.pathname);
fetch('/api/config').then(r=>r.json()).then(async c=>{config=c;if(!inviteToken&&typeof localStorage!=='undefined'){try{const saved=JSON.parse(localStorage.getItem('trustlane-session')||'null');if(saved?.refresh_token){refreshSecret=saved.refresh_token;rememberSession=true;await refreshSession();if(token&&user)await load();}}catch(e){clearSession();msg.textContent='Please sign in again.'}}if(inviteToken){token=inviteToken;try{user=await api('/auth/v1/user');$('#login').hidden=true;$('#setup').hidden=false}catch(e){token=null;msg.textContent='The invitation has expired. Ask an administrator for a new invitation.'}}}).catch(()=>msg.textContent='Portal is temporarily unavailable.');
$('#setup-form').onsubmit=async e=>{e.preventDefault();try{await api('/auth/v1/user',{method:'PUT',body:JSON.stringify({password:new FormData(e.target).get('password')})});$('#setup').hidden=true;await load();msg.textContent='Password set.'}catch(err){msg.textContent=err.message}};

async function agentAction(payload){const response=await fetch('/api/agents',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify(payload)});const data=await response.json();if(!response.ok)throw Error(data.error||'Request failed.');return data;}
$('#invite-form').onsubmit=async e=>{e.preventDefault();try{await agentAction({action:'invite',...Object.fromEntries(new FormData(e.target))});e.target.reset();await load();msg.textContent='Agent invitation sent.'}catch(err){msg.textContent=err.message}};
$('#terms-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;try{await api('/rest/v1/rpc/trustlane_publish_agreement_terms',{method:'POST',body:JSON.stringify({p_body:new FormData(form).get('body')})});form.reset();msg.textContent='Agreement terms published for new booking links.'}catch(err){msg.textContent=err.message}finally{button.disabled=false}};
$('#create-agent-form').onsubmit=async e=>{e.preventDefault();const form=e.target;const button=form.querySelector('button');button.disabled=true;try{await agentAction({action:'create',...Object.fromEntries(new FormData(form))});form.reset();await load();msg.textContent='Agent account created.'}catch(err){msg.textContent=err.message}finally{button.disabled=false}};
$('#agent-list').onclick=async e=>{const b=e.target.closest('[data-agent]');if(!b)return;try{await agentAction({action:b.dataset.active==='true'?'deactivate':'reactivate',user_id:b.dataset.agent});await load();msg.textContent='Agent access updated.'}catch(err){msg.textContent=err.message}};
